import { createEnv } from '@tpmjs/env';
import { z } from 'zod';

export const env = createEnv({
  NODE_ENV: z.enum(['development', 'production', 'test']).default('development'),
  NEXT_PUBLIC_API_URL: z.string().url().optional(),
  CRON_SECRET: z.string().min(32).optional(), // Required for Vercel Cron security
  RAILWAY_EXECUTOR_URL: z
    .string()
    .url()
    .default('https://endearing-commitment-production.up.railway.app'), // Railway service for health checks

  // Better Auth
  BETTER_AUTH_SECRET: z.string().min(32).optional(), // Required for session encryption
  BETTER_AUTH_URL: z.string().url().optional(), // Base URL for auth callbacks

  // Resend (Email)
  RESEND_API_KEY: z.string().startsWith('re_').optional(), // Resend API key for sending emails

  // Discord Summary Agent
  DISCORD_SUMMARY_AGENT_ID: z.string().optional(), // Agent ID for Discord summary cron
  DISCORD_GUILD_ID: z.string().optional(), // Discord server ID to summarize
  DISCORD_SUMMARY_CHANNEL_ID: z.string().optional(), // Channel to post summaries to
});

input.content:
name: Auto-Fix Production Error

on:
  issues:
    types: [labeled]
  workflow_dispatch:
    inputs:
      issue_number:
        description: 'Issue number to process'
        required: true
        type: number

jobs:
  trigger-claude:
    if: github.repository_owner == 'tpmjs' && (github.event.label.name == 'auto-fix' || github.event_name == 'workflow_dispatch')
    runs-on: ubuntu-latest
    permissions:
      issues: write

    steps:
      - name: Check for retry loop
        id: loop-check
        uses: actions/github-script@v7
        with:
          script: |
            const issueNumber = context.issue?.number || ${{ inputs.issue_number || 0 }};
            const events = await github.rest.issues.listEvents({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issueNumber,
              per_page: 100
            });

            const autoFixLabelEvents = events.data.filter(
              e => e.event === 'labeled' && e.label?.name === 'auto-fix'
            );

            if (autoFixLabelEvents.length >= 2) {
              // Too many retries — escalate
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issueNumber,
                name: 'auto-fix'
              }).catch(() => {});

              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issueNumber,
                labels: ['needs-human-review']
              });

              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issueNumber,
                body: '## Auto-fix limit reached\n\nThis issue has been through 2+ auto-fix attempts without resolution. Escalating to human review.\n\nPlease investigate manually and remove the `needs-human-review` label when resolved.'
