  1→import { prisma } from '@tpmjs/db';
  2→import { type NextRequest, NextResponse } from 'next/server';
  3→
  4→export const runtime = 'nodejs';
  5→export const dynamic = 'force-dynamic';
  6→export const maxDuration = 30;
  7→
  8→interface HealthCheckReport {
  9→  timestamp: string;
 10→  source: string;
 11→  runId?: string;
 12→  checks: Record<string, 'pass' | 'fail' | undefined>;
 13→}
 14→
 15→/**
 16→ * POST /api/health/report
 17→ * Receives health check reports from GitHub Actions or other monitoring systems
 18→ * Requires CRON_SECRET authorization
 19→ */
 20→export async function POST(request: NextRequest) {
 21→  // Verify authorization
 22→  const authHeader = request.headers.get('authorization');
 23→  const expectedToken = process.env.CRON_SECRET;
 24→
 25→  if (!expectedToken || authHeader !== `Bearer ${expectedToken}`) {
 26→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 27→  }
 28→
 29→  try {
 30→    const report: HealthCheckReport = await request.json();
 31→
 32→    // Calculate overall status
 33→    const checkResults = Object.values(report.checks);
 34→    const passCount = checkResults.filter((r) => r === 'pass').length;
 35→    const failCount = checkResults.filter((r) => r === 'fail').length;
 36→    const totalChecks = checkResults.length;
 37→    const overallStatus =
 38→      failCount === 0 ? 'healthy' : failCount < totalChecks / 2 ? 'degraded' : 'down';
 39→
 40→    // Store the report in the database
 41→    await prisma.endpointHealthReport.create({
 42→      data: {
 43→        timestamp: new Date(report.timestamp),
 44→        source: report.source,
 45→        runId: report.runId,
 46→        checks: report.checks,
 47→        passCount,
 48→        failCount,
 49→        totalChecks,
 50→        overallStatus,
 51→      },
 52→    });
 53→
 54→    // Clean up old reports (keep last 7 days)
 55→    const cutoffDate = new Date();
 56→    cutoffDate.setDate(cutoffDate.getDate() - 7);
 57→    await prisma.endpointHealthReport.deleteMany({
 58→      where: { timestamp: { lt: cutoffDate } },
 59→    });
 60→
 61→    return NextResponse.json({
 62→      success: true,
 63→      data: {
 64→        recorded: true,
 65→        overallStatus,
 66→        passCount,
 67→        failCount,
 68→        totalChecks,
 69→      },
 70→    });
 71→  } catch (error) {
 72→    console.error('[Health Report] Error:', error);
 73→    return NextResponse.json(
 74→      { error: error instanceof Error ? error.message : 'Internal error' },
 75→      { status: 500 }
 76→    );
 77→  }
 78→}
 79→
 80→/**
 81→ * GET /api/health/report
 82→ * Returns recent health check reports
 83→ */
 84→export async function GET(request: NextRequest) {
 85→  const { searchParams } = new URL(request.url);
 86→  const limit = Math.min(parseInt(searchParams.get('limit') || '50', 10), 200);
 87→  const hours = Math.min(parseInt(searchParams.get('hours') || '24', 10), 168); // Max 7 days
 88→
 89→  try {
 90→    const cutoffDate = new Date();
 91→    cutoffDate.setHours(cutoffDate.getHours() - hours);
 92→
 93→    const reports = await prisma.endpointHealthReport.findMany({
 94→      where: { timestamp: { gte: cutoffDate } },
 95→      orderBy: { timestamp: 'desc' },
 96→      take: limit,
 97→    });
 98→
 99→    // Calculate summary stats
100→    const totalReports = reports.length;
101→    const healthyCount = reports.filter((r) => r.overallStatus === 'healthy').length;
102→    const degradedCount = reports.filter((r) => r.overallStatus === 'degraded').length;
103→    const downCount = reports.filter((r) => r.overallStatus === 'down').length;
104→
105→    // Calculate uptime percentage
106→    const uptimePercent =
107→      totalReports > 0 ? ((healthyCount / totalReports) * 100).toFixed(2) : '100.00';
108→
109→    // Get per-check statistics
110→    const checkStats: Record<string, { pass: number; fail: number; total: number }> = {};
111→    for (const report of reports) {
112→      const checks = report.checks as Record<string, string>;
113→      for (const [checkName, status] of Object.entries(checks)) {
114→        if (!checkStats[checkName]) {
115→          checkStats[checkName] = { pass: 0, fail: 0, total: 0 };
116→        }
117→        checkStats[checkName].total++;
118→        if (status === 'pass') {
119→          checkStats[checkName].pass++;
120→        } else if (status === 'fail') {
121→          checkStats[checkName].fail++;
122→        }
123→      }
124→    }
125→
126→    // Get current status (latest report)
127→    const latestReport = reports[0];
128→    const currentStatus = latestReport?.overallStatus || 'unknown';
129→    const lastChecked = latestReport?.timestamp || null;
130→
131→    return NextResponse.json({
132→      success: true,
133→      data: {
134→        currentStatus,
135→        lastChecked,
136→        summary: {
137→          totalReports,
138→          healthy: healthyCount,
139→          degraded: degradedCount,
140→          down: downCount,
141→          uptimePercent: `${uptimePercent}%`,
142→          timeRange: `${hours} hours`,
143→        },
144→        checkStats: Object.entries(checkStats).map(([name, stats]) => ({
145→          name,
146→          ...stats,
147→          successRate:
148→            stats.total > 0 ? `${((stats.pass / stats.total) * 100).toFixed(1)}%` : 'N/A',
149→        })),
150→        recentReports: reports.slice(0, 20).map((r) => ({
151→          id: r.id,
152→          timestamp: r.timestamp,
153→          source: r.source,
154→          runId: r.runId,
155→          overallStatus: r.overallStatus,
156→          passCount: r.passCount,
157→          failCount: r.failCount,
158→          totalChecks: r.totalChecks,
159→          checks: r.checks,
160→        })),
