    toolsWithScores.sort((a, b) => b.trendingScore - a.trendingScore);

    return NextResponse.json({
      success: true,
      data: toolsWithScores,
      meta: {
        version: API_VERSION,
        timestamp: new Date().toISOString(),
        requestId,
        fieldCount: requestedFieldCount,
      },
      pagination: {
        limit,
        offset,
        hasMore,
      },
    });
